content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1000px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  background-color: var(--card-bg);
  padding: 20px 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.header p {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-top: 4px;
}

.main-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .main-layout {
    grid-template-columns: 1fr 1fr;
  }
}

.chart-section {
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
}

.total-card {
  text-align: center;
  margin-bottom: 16px;
  width: 100%;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-color);
}

.total-card .label {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.total-card .amount {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-top: 4px;
}

.detail-section {
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.detail-section h2 {
  font-size: 1.25rem;
  font-weight: 600;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 12px;
}

.expense-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 320px;
  overflow-y: auto;
  padding-right: 4px;
}

.expense-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.expense-item:hover {
  background-color: #f1f5f9;
  border-color: var(--primary-color);
}

.expense-item.selected {
  background-color: #e0e7ff;
  border-color: var(--primary-color);
}

.expense-item .item-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.expense-item .color-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
}

.expense-item .category {
  font-weight: 500;
  font-size: 0.95rem;
}

.expense-item .amount {
  font-weight: 600;
  font-size: 0.95rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background-color 0.2s;
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

export interface ExpenseItem {
  id: string;
  category: string;
  amount: number;
  color: string;
  memo: string;
}

import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip, Legend } from 'recharts';
import { ExpenseItem } from './types';

interface ExpenseChartProps {
  items: ExpenseItem[];
  selectedId: string;
  onSelect: (id: string) => void;
}

export default function ExpenseChart({ items = [], selectedId, onSelect }: ExpenseChartProps) {
  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY' }).format(val);
  };

  return (
    <div className="chart-section">
      <div className="total-card">
        <div className="label">総支出金額</div>
        <div className="amount">{formatCurrency(items.reduce((acc, cur) => acc + cur.amount, 0))}</div>
      </div>

      <div style={{ width: '100%', height: 280 }}>
        <ResponsiveContainer>
          <PieChart>
            <Pie
              data={items}
              dataKey="amount"
              nameKey="category"
              cx="50%"
              cy="50%"
              outerRadius={90}
              innerRadius={45}
              paddingAngle={2}
              onClick={(data) => {
                if (data && data.id) {
                  onSelect(data.id);
                }
              }}
              style={{ cursor: 'pointer' }}
            >
              {items.map((entry) => (
                <Cell
                  key={`cell-${entry.id}`}
                  fill={entry.color}
                  stroke={entry.id === selectedId ? '#1e293b' : '#ffffff'}
                  strokeWidth={entry.id === selectedId ? 2 : 1}
                />
              ))}
            </Pie>
            <Tooltip
              formatter={(value: number) => [formatCurrency(value), '金額']}
            />
            <Legend
              formatter={(value) => <span style={{ fontSize: '0.85rem', color: '#1e293b' }}>{value}</span>}
              layout="horizontal"
              verticalAlign="bottom"
              align="center"
            />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { ExpenseItem } from './types';
import ExpenseChart from './ExpenseChart';
import './index.css';

const initialExpenses: ExpenseItem[] = [
  { id: '1', category: '食費', amount: 45000, color: '#4f46e5', memo: 'スーパーでの食材購入、外食ランチ含む' },
  { id: '2', category: '住居費', amount: 80000, color: '#06b6d4', memo: '家賃・共益費' },
  { id: '3', category: '光熱費', amount: 12000, color: '#10b981', memo: '電気・ガス・水道の合算' },
  { id: '4', category: '通信費', amount: 8000, color: '#f59e0b', memo: 'スマートフォン及び自宅Wi-Fi' },
  { id: '5', category: '交通費', amount: 10000, color: '#ef4444', memo: '通勤定期・タクシー代など' },
  { id: '6', category: '娯楽費', amount: 15000, color: '#8b5cf6', memo: '映画、書籍、趣味の道具' },
  { id: '7', category: 'その他', amount: 5000, color: '#ec4899', memo: '日用品や急な雑費' },
];

export default function App() {
  const [expenses, setExpenses] = useState<ExpenseItem[]>(initialExpenses);
  const [selectedId, setSelectedId] = useState<string>(initialExpenses[0].id);

  // メモ編集用の状態
  const [memoInput, setMemoInput] = useState<string>(initialExpenses[0].memo);

  // 新規追加用の状態
  const [categoryInput, setCategoryInput] = useState('');
  const [amountInput, setAmountInput] = useState('');
  const [colorInput, setColorInput] = useState('#4f46e5');
  const [memoAddInput, setMemoAddInput] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);

  const selectedItem = expenses.find((item) => item.id === selectedId) || expenses[0];

  const handleSelect = (id: string) => {
    setSelectedId(id);
    const item = expenses.find((e) => e.id === id);
    if (item) {
      setMemoInput(item.memo);
    }
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY' }).format(val);
  };

  const handleSaveMemo = () => {
    setExpenses((prev) =>
      prev.map((item) => (item.id === selectedId ? { ...item, memo: memoInput } : item))
    );
  };

  const handleAddExpense = (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryInput || !amountInput) return;

    const newItem: ExpenseItem = {
      id: Date.now().toString(),
      category: categoryInput,
      amount: Number(amountInput),
      color: colorInput,
      memo: memoAddInput,
    };

    setExpenses((prev) => [...prev, newItem]);
    setCategoryInput('');
    setAmountInput('');
    setMemoAddInput('');
    setShowAddForm(false);
    setSelectedId(newItem.id);
    setMemoInput(newItem.memo);
  };

  const handleDeleteExpense = (id: string) => {
    if (expenses.length <= 1) {
      alert('最低1つの項目が必要です。');
      return;
    }
    const filtered = expenses.filter((item) => item.id !== id);
    setExpenses(filtered);
    if (selectedId === id) {
      setSelectedId(filtered[0].id);
      setMemoInput(filtered[0].memo);
    }
  };

  return (
    <div className="app-container">
      <header className="header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
        <div>
          <h1>家計簿ダッシュボード</h1>
          <p>支出の円グラフをクリックするか、リストから項目を選択して詳細を確認できます。</p>
        </div>
        <button className="btn btn-primary" onClick={() => setShowAddForm(!showAddForm)}>
          {showAddForm ? '閉じる' : '+ 新規支出を追加'}
        </button>
      </header>

      {showAddForm && (
        <form onSubmit={handleAddExpense} style={{ backgroundColor: 'var(--card-bg)', padding: '20px', borderRadius: 'var(--radius)', border: '1px solid var(--border-color)', boxShadow: 'var(--shadow)', display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <h3 style={{ fontSize: '1rem', fontWeight: 600 }}>新しい支出項目を追加</h3>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
            <div>
              <label style={{ fontSize: '0.85rem', color: 'var(--text-muted)', display: 'block', marginBottom: '4px' }}>カテゴリ名</label>
              <input
                type="text"
                value={categoryInput}
                onChange={(e) => setCategoryInput(e.target.value)}
                placeholder="例: 医療費"
                required
                style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid var(--border-color)' }}
              />
            </div>
            <div>
              <label style={{ fontSize: '0.85rem', color: 'var(--text-muted)', display: 'block', marginBottom: '4px' }}>金額 (円)</label>
              <input
                type="number"
                value={amountInput}
                onChange={(e) => setAmountInput(e.target.value)}
                placeholder="例: 5000"
                required
                style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid var(--border-color)' }}
              />
            </div>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '12px' }}>
            <div>
              <label style={{ fontSize: '0.85rem', color: 'var(--text-muted)', display: 'block', marginBottom: '4px' }}>カラー</label>
              <input
                type="color"
                value={colorInput}
                onChange={(e) => setColorInput(e.target.value)}
                style={{ width: '100%', height: '36px', padding: '2px', borderRadius: '6px', border: '1px solid var(--border-color)', cursor: 'pointer' }}
              />
            </div>
            <div>
              <label style={{ fontSize: '0.85rem', color: 'var(--text-muted)', display: 'block', marginBottom: '4px' }}>メモ</label>
              <input
                type="text"
                value={memoAddInput}
                onChange={(e) => setMemoAddInput(e.target.value)}
                placeholder="メモを入力..."
                style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid var(--border-color)' }}
              />
            </div>
          </div>
          <button type="submit" className="btn btn-primary" style={{ alignSelf: 'flex-start', marginTop: '4px' }}>追加する</button>
        </form>
      )}

      <div className="main-layout">
        <ExpenseChart items={expenses} selectedId={selectedId} onSelect={handleSelect} />

        <div className="detail-section">
          <h2>支出項目の詳細</h2>

          <div className="expense-list">
            {expenses.map((item) => {
              const isSelected = item.id === selectedId;
              return (
                <div
                  key={item.id}
                  className={`expense-item ${isSelected ? 'selected' : ''}`}
                  onClick={() => handleSelect(item.id)}
                >
                  <div className="item-info">
                    <span className="color-dot" style={{ backgroundColor: item.color }} />
                    <span className="category">{item.category}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <span className="amount">{formatCurrency(item.amount)}</span>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteExpense(item.id);
                      }}
                      style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: '0.8rem' }}
                      title="削除"
                    >
                      ✕
                    </button>
                  </div>
                </div>
              );
            })}
          </div>

          {selectedItem && (
            <div style={{ marginTop: 'auto', paddingTop: '16px', borderTop: '1px solid var(--border-color)', display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <h3 style={{ fontSize: '1rem', fontWeight: 600 }}>
                {selectedItem.category} のメモ
              </h3>
              <textarea
                value={memoInput}
                onChange={(e) => setMemoInput(e.target.value)}
                rows={3}
                style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid var(--border-color)', fontSize: '0.9rem', resize: 'vertical' }}
              />
              <button className="btn btn-primary" onClick={handleSaveMemo} style={{ alignSelf: 'flex-start' }}>
                メモを保存する
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
